mapper.select:
SELECT A.*, B.* FROM ( SELECT tt1.rnum no, tt1.image_id, tt1.content_id, tt1.image_url, TO_CHAR(tt1.created_dt, 'YYYY-MM-DD HH24:MI:SS') created_dt FROM ( SELECT ROWNUM rnum, t1.* FROM ( SELECT * FROM content_image
ORDER BY content_id ASC, image_id ASC ) t1 WHERE ROWNUM <= (#{pageSize} * (#{pageNo} - 1) + #{pageSize}) ) tt1 WHERE rnum >= (#{pageSize} * (#{pageNo} - 1) + 1) ) A CROSS JOIN ( SELECT COUNT(*) total_cnt FROM content_image
) B

mapper.update:
UPDATE content_image
   SET content_id = #{contentId},
       image_url  = #{imageUrl, jdbcType=VARCHAR}
 WHERE image_id = #{imageId}
